// alerts-polling-to-slack.json과 동일한 '최근 폴링 주기 내 생성분만' 시간창 필터.
// Notion은 실시간 알림이 아니라 '누적 기록'이 목적이라 INFO를 포함한 전체를 남길 수도 있지만,
// 실제 모드는 20초마다 도는 루프라 INFO까지 전부 쌓으면 하루 수천 행이 생겨 그대로는 비현실적임 —
// 기본값은 threat_level이 INFO가 아닌 것만 Notion에 축적한다. 전체를 원하면 아래 필터 줄을 지우면 된다.
const body = $input.first().json;
const history = body.history || [];
const cutoff = Date.now() - 15 * 60 * 1000;
return history
  .filter((h) => h.created_at && new Date(h.created_at).getTime() > cutoff)
  .filter((h) => h.threat_level && h.threat_level !== 'INFO')
  .map((h) => ({ json: h }));

const h = $json;
const events = h.events || [];
const topCategories = [...new Set(events.map((e) => e.category))].slice(0, 3).join(', ');
return {
  json: {
    title: `[${h.threat_level}] 분석 #${h.id}`,
    threat_level: h.threat_level,
    summary: h.summary || '',
    event_count: events.length,
    categories: topCategories,
    mode: h.mode || 'real',
    analysis_id: h.id,
    occurred_at: h.created_at ? new Date(h.created_at).toISOString() : null,
    report_url: `http://host.docker.internal:8000/api/attack-monitor/report/${h.id}?mode=real`
  }
};
